<?php $id=(int)($_GET['id']??0); $r=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT * FROM alat WHERE idalat=$id")); $kat=mysqli_query($koneksi,"SELECT * FROM kategori ORDER BY namakategori"); ?><h2>Edit Sarana</h2><form action="proses/prosesalat.php?aksi=edit" method="post" enctype="multipart/form-data"><input type="hidden" name="idalat" value="<?=$r['idalat']?>"><div class="form-group"><label>Nama Alat</label><input class="form-control" name="namaalat" value="<?=htmlspecialchars($r['namaalat'])?>" required></div><div class="form-group"><label>Foto Sarana</label><?php if(!empty($r['foto'])): ?><div class="mb-2"><img src="assets/uploads/sarana/<?=htmlspecialchars($r['foto'])?>" alt="Foto sarana" style="width:110px;height:85px;object-fit:cover;border-radius:8px"></div><?php endif; ?><input class="form-control-file" type="file" name="foto" accept="image/jpeg,image/png,image/webp"><small class="text-muted">Kosongkan jika tidak ingin mengganti foto.</small></div><div class="form-group"><label>Kategori</label><select class="form-control" name="idkategori"><?php while($k=mysqli_fetch_assoc($kat)): ?><option value="<?=$k['idkategori']?>" <?=$k['idkategori']==$r['idkategori']?'selected':''?>><?=htmlspecialchars($k['namakategori'])?></option><?php endwhile;?></select></div><div class="form-row"><div class="form-group col"><label>Jumlah</label><input class="form-control" type="number" name="jumlah" value="<?=$r['jumlah']?>" required></div><div class="form-group col"><label>Kondisi</label><input class="form-control" name="kondisi" value="<?=htmlspecialchars($r['kondisi'])?>" required></div><div class="form-group col"><label>Lokasi</label><input class="form-control" name="lokasi" value="<?=htmlspecialchars($r['lokasi'])?>" required></div></div><button class="btn btn-primary">Simpan</button></form>